cd /testbed && c++ -std=c++23 -Iinclude -x c++ - -Lbuild -lfmt -o build/range-repro <<'EOF'
#include <ranges>
#include <string>
#include <fmt/ranges.h>
struct X {
  template <std::ranges::range R> X(R&& r)
      : sv(&*std::ranges::begin(r), std::ranges::distance(r)) {}
  auto begin() { return sv.begin(); }
  auto end() { return sv.end(); }
  std::string_view sv;
};
int main() {
  std::string line = "a,b-c,d-e,f";
  fmt::print("{}\n", line | std::views::split(','));
  auto x = line | std::views::split(',')
                | std::views::transform([](auto part) { return X(part); });
  fmt::print("{}\n", x);
  auto y = line | std::views::split(',')
                | std::views::transform(std::views::split('-'));
  fmt::print("{}\n", y);
}
EOF

