cd /testbed && patch -p1 <<'PATCH'
--- a/test/ranges-test.cc
+++ b/test/ranges-test.cc
@@ -17,6 +17,10 @@

 #include "gtest/gtest.h"

+#ifdef __cpp_lib_ranges
+#  include <ranges>
+#endif
+
 #if !FMT_GCC_VERSION || FMT_GCC_VERSION >= 601
 #  define FMT_RANGES_TEST_ENABLE_C_STYLE_ARRAY
 #endif
@@ -456,3 +460,66 @@
 TEST(ranges_test, vector_char) {
   EXPECT_EQ(fmt::format("{}", std::vector<char>{'a', 'b'}), "['a', 'b']");
 }
+
+TEST(ranges_test, nested_debug_format) {
+  auto chars = std::vector<std::vector<char>>{{'a'}, {'b', '\n'}};
+  EXPECT_EQ(fmt::format("{}", chars), "[['a'], ['b', '\\n']]");
+  EXPECT_EQ(fmt::format("{:n}", chars), "['a'], ['b', '\\n']");
+  EXPECT_EQ(fmt::format("{::}", chars), "[['a'], ['b', '\\n']]");
+  EXPECT_EQ(fmt::format("{:::}", chars), "[[a], [b, \n]]");
+
+  auto strings = std::vector<std::vector<std::string>>{{"a"}, {"b", "\n"}};
+  EXPECT_EQ(fmt::format("{}", strings), "[[\"a\"], [\"b\", \"\\n\"]]");
+  EXPECT_EQ(fmt::format("{:::}", strings), "[[a], [b, \n]]");
+}
+
+struct temporary_range {
+  struct iterator {
+    non_const_only_range<char> operator*() const {
+      return non_const_only_range<char>{'a', 'b'};
+    }
+    void operator++() { ++pos; }
+    bool operator!=(iterator other) const { return pos != other.pos; }
+    int pos;
+  };
+
+  iterator begin() const { return {0}; }
+  iterator end() const { return {2}; }
+};
+
+TEST(ranges_test, temporary_non_const_range) {
+  EXPECT_EQ(fmt::format("{}", temporary_range{}),
+            "[['a', 'b'], ['a', 'b']]");
+}
+
+#ifdef __cpp_lib_ranges
+struct split_range {
+  std::string_view sv;
+
+  template <std::ranges::range R>
+  explicit split_range(R&& r)
+      : sv(&*std::ranges::begin(r), std::ranges::distance(r)) {}
+
+  auto begin() { return sv.begin(); }
+  auto end() { return sv.end(); }
+};
+
+TEST(ranges_test, split_view) {
+  std::string line = "a,b-c,d-e,f";
+  EXPECT_EQ(fmt::format("{}", line | std::views::split(',')),
+            "[['a'], ['b', '-', 'c'], ['d', '-', 'e'], ['f']]");
+}
+
+TEST(ranges_test, transformed_split_view) {
+  std::string line = "a,b-c,d-e,f";
+  auto x = line | std::views::split(',') |
+           std::views::transform([](auto part) { return split_range(part); });
+  EXPECT_EQ(fmt::format("{}", x),
+            "[['a'], ['b', '-', 'c'], ['d', '-', 'e'], ['f']]");
+
+  auto y = line | std::views::split(',') |
+           std::views::transform(std::views::split('-'));
+  EXPECT_EQ(fmt::format("{}", y),
+            "[[['a']], [['b'], ['c']], [['d'], ['e']], [['f']]]");
+}
+#endif
PATCH
cmake -B build -S . -DCMAKE_CXX_STANDARD=23 > build/range-configure.log && cmake --build build --parallel 4 --target ranges-test > build/range-build.log 2>&1; status=$?; tail -16 build/range-build.log; exit "$status"

cd /testbed && patch -p1 <<'PATCH'
--- a/include/fmt/ranges.h
+++ b/include/fmt/ranges.h
@@ -473,19 +473,15 @@
   FMT_CONSTEXPR auto parse(ParseContext& ctx) -> decltype(ctx.begin()) {
     auto it = ctx.begin();
     auto end = ctx.end();
-    if (it == end || *it == '}') {
-      maybe_set_debug_format();
-      return it;
-    }
-
-    if (*it == 'n') {
+    if (it != end && *it == 'n') {
       set_brackets({}, {});
       ++it;
     }

-    if (*it == '}') {
+    if (it == end || *it == '}') {
       maybe_set_debug_format();
-      return it;
+      ctx.advance_to(it);
+      return underlying_.parse(ctx);
     }

     if (*it != ':')
@@ -509,7 +505,8 @@
       if (i > 0) out = detail::copy_str<Char>(separator_, out);
       ;
       ctx.advance_to(out);
-      out = underlying_.format(mapper.map(*it), ctx);
+      auto&& item = *it;
+      out = underlying_.format(mapper.map(item), ctx);
       ++i;
     }
     out = detail::copy_str<Char>(closing_bracket_, out);
--- a/test/ranges-test.cc
+++ b/test/ranges-test.cc
@@ -444,7 +444,7 @@
 struct temporary_range {
   struct iterator {
     non_const_only_range<char> operator*() const {
-      return non_const_only_range<char>{'a', 'b'};
+      return non_const_only_range<char>(std::vector<char>{'a', 'b'});
     }
     void operator++() { ++pos; }
     bool operator!=(iterator other) const { return pos != other.pos; }
--- a/doc/api.rst
+++ b/doc/api.rst
@@ -450,6 +450,10 @@
   fmt::print("{}", t);


+Nested ranges are formatted recursively, with characters and strings quoted and
+escaped by default. This also applies to C++20 range views, including views that
+produce temporary ranges with non-const ``begin()`` and ``end()``.
+
 NOTE: currently, the overload of ``fmt::join`` for iterables exists in the main
 ``format.h`` header, but expect this to change in the future.
PATCH
cmake --build build --parallel 4 --target ranges-test > build/range-build.log 2>&1 && ctest --test-dir build -V -R '^ranges-test$' > build/range-test.log 2>&1; status=$?; if [ "$status" -ne 0 ]; then tail -65 build/range-build.log; fi; tail -18 build/range-test.log; exit "$status"

cd /testbed && patch --no-backup-if-mismatch -p1 <<'PATCH'
--- a/include/fmt/ranges.h
+++ b/include/fmt/ranges.h
@@ -505,6 +505,7 @@
       if (i > 0) out = detail::copy_str<Char>(separator_, out);
       ;
       ctx.advance_to(out);
+      // Bind temporary elements to an lvalue to allow non-const formatters.
       auto&& item = *it;
       out = underlying_.format(mapper.map(item), ctx);
       ++i;
--- a/test/ranges-test.cc
+++ b/test/ranges-test.cc
@@ -455,8 +455,7 @@
 };

 TEST(ranges_test, temporary_non_const_range) {
-  EXPECT_EQ(fmt::format("{}", temporary_range{}),
-            "[['a', 'b'], ['a', 'b']]");
+  EXPECT_EQ(fmt::format("{}", temporary_range{}), "[['a', 'b'], ['a', 'b']]");
 }
PATCH
rm -f doc/api.rst.orig test/ranges-test.cc.orig build/range-repro build/range-repro-x build/range-repro-debug build/range-configure.log build/range-build.log build/range-test.log build/range-related-build.log build/range-related-test.log build/range-cxx20-configure.log build/range-cxx20-build.log build/range-cxx20-test.log build/range-cxx11-configure.log build/range-cxx11-build.log build/range-cxx11-test.log
cmake --build build --parallel 4 --target ranges-test > /dev/null && ctest --test-dir build -V -R '^ranges-test$' | tail -12 && git diff --check && git status --short

